-- CitizenAware Government Schemes Dataset SQL Export
-- Total Records: 1000

CREATE TABLE IF NOT EXISTS government_schemes (
    id VARCHAR(50) PRIMARY KEY,
    scheme_name VARCHAR(255) NOT NULL UNIQUE,
    scheme_type VARCHAR(50),
    state VARCHAR(100),
    department VARCHAR(255),
    category VARCHAR(100),
    description TEXT,
    eligibility TEXT,
    minimum_age INT,
    maximum_age INT,
    gender VARCHAR(20),
    income_limit VARCHAR(50),
    occupation VARCHAR(100),
    caste VARCHAR(50),
    disability VARCHAR(100),
    benefits TEXT,
    required_documents TEXT,
    application_mode VARCHAR(50),
    official_website VARCHAR(255),
    helpline_number VARCHAR(50),
    status VARCHAR(50),
    keywords TEXT
);

